#' Shift-Share (Bartik) IV
#'
#' 
#' @param data .
#' @param outcome .
#' @param endog .
#' @param region .
#' @param sector .
#' @param share .
#' @param shock .
#' @param controls .
#' @param weights .
#' @param regionCluster .
#' @param sectorCluster .
#' @param sumShares .
#' @param h0 .
#' @param level .
#' @param showStages .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$info} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$iv} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$stages} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$info$asDF}
#'
#' \code{as.data.frame(results$info)}
#'
#' @export
shiftshare <- function(
    data,
    outcome,
    endog,
    region,
    sector,
    share,
    shock,
    controls,
    weights,
    regionCluster,
    sectorCluster,
    sumShares = FALSE,
    h0 = 0,
    level = 95,
    showStages = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("shiftshare requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(endog)) endog <- jmvcore::resolveQuo(jmvcore::enquo(endog))
    if ( ! missing(region)) region <- jmvcore::resolveQuo(jmvcore::enquo(region))
    if ( ! missing(sector)) sector <- jmvcore::resolveQuo(jmvcore::enquo(sector))
    if ( ! missing(share)) share <- jmvcore::resolveQuo(jmvcore::enquo(share))
    if ( ! missing(shock)) shock <- jmvcore::resolveQuo(jmvcore::enquo(shock))
    if ( ! missing(controls)) controls <- jmvcore::resolveQuo(jmvcore::enquo(controls))
    if ( ! missing(weights)) weights <- jmvcore::resolveQuo(jmvcore::enquo(weights))
    if ( ! missing(regionCluster)) regionCluster <- jmvcore::resolveQuo(jmvcore::enquo(regionCluster))
    if ( ! missing(sectorCluster)) sectorCluster <- jmvcore::resolveQuo(jmvcore::enquo(sectorCluster))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(endog), endog, NULL),
            `if`( ! missing(region), region, NULL),
            `if`( ! missing(sector), sector, NULL),
            `if`( ! missing(share), share, NULL),
            `if`( ! missing(shock), shock, NULL),
            `if`( ! missing(controls), controls, NULL),
            `if`( ! missing(weights), weights, NULL),
            `if`( ! missing(regionCluster), regionCluster, NULL),
            `if`( ! missing(sectorCluster), sectorCluster, NULL))


    options <- shiftshareOptions$new(
        outcome = outcome,
        endog = endog,
        region = region,
        sector = sector,
        share = share,
        shock = shock,
        controls = controls,
        weights = weights,
        regionCluster = regionCluster,
        sectorCluster = sectorCluster,
        sumShares = sumShares,
        h0 = h0,
        level = level,
        showStages = showStages,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- shiftshareClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

